<a href="@Href"
   class="block w-full max-w-xs mx-auto transition-all duration-300 hover:scale-105"
   @onmouseenter="() => OnHover(true)"
   @onmouseleave="() => OnHover(false)">
    <div class="relative h-48"
         style="@GetBackgroundStyles(IsHovered)">
    </div>
    <p class="text-center font-bold font-mono text-white text-lg mt-2 drop-shadow-lg">@Heading</p>
</a>

@code {
    private bool IsHovered { get; set; } = false;

    [Parameter]
    public string Heading { get; set; } = string.Empty;

    [Parameter]
    public string Text { get; set; } = string.Empty;

    [Parameter]
    public string Href { get; set; } = string.Empty;

    private void OnHover(bool isHovered)
    {
        IsHovered = isHovered;
        StateHasChanged(); // Add this - WASM needs explicit refresh
    }

    private string GetBackgroundStyles(bool hovered)
    {
        var baseStyles = "background-size: contain; background-repeat: no-repeat; background-position: center; image-rendering: pixelated; image-rendering: crisp-edges;";
        var image = hovered ? "folder_open.png" : "folder_closed.png";

        // Ensure the path is correct for WASM
        // WASM serves files from the wwwroot folder
        var imagePath = $"images/components/{image}";

        return $"{baseStyles} background-image: url('{imagePath}');";
    }
}

